# Assemble existing parsed runs; never executes HYSPLIT.
files <- c("validate_facilities.R", "read_facility_exchange_config.R", "prepare_receptor_facilities.R", "sample_hourly_plume_at_receptors.R", "summarize_receptor_time_series.R", "classify_receptor_intercepts.R", "build_source_receptor_exchange.R", "write_facility_receptor_outputs.R", "extract_facility_receptors_from_plume.R", "discover_parsed_run_inventory.R", "validate_parsed_run_inventory.R", "combine_source_receptor_exchanges.R", "process_parsed_run_inventory.R", "summarize_connectivity_by_time.R", "summarize_connectivity_by_source.R", "summarize_connectivity_by_receptor.R", "summarize_connectivity_by_dyad.R", "build_facility_connectivity_matrices.R", "write_multirun_connectivity_outputs.R", "assemble_multirun_facility_connectivity.R")
invisible(lapply(file.path("R", files), source))
parse_args <- function(args) { out <- list(write = FALSE, no_write = FALSE, overwrite = FALSE, stop_on_error = FALSE); i <- 1L; while (i <= length(args)) { if (args[[i]] %in% c("--write", "--no-write", "--overwrite", "--stop-on-error")) { out[[gsub("-", "_", sub("^--", "", args[[i]]))]] <- TRUE; i <- i + 1L } else if (args[[i]] %in% c("--manifest", "--facilities", "--config", "--run-root")) { if (i == length(args)) stop("Missing value after ", args[[i]]); out[[gsub("-", "_", sub("^--", "", args[[i]]))]] <- args[[i + 1L]]; i <- i + 2L } else stop("Unknown argument: ", args[[i]]) }; if (!all(c("manifest", "facilities", "config", "run_root") %in% names(out))) stop("Manifest, facilities, config, and run-root are required."); if (identical(out$write, out$no_write)) stop("Specify exactly one of --write or --no-write."); out }
tryCatch({ args <- parse_args(commandArgs(trailingOnly = TRUE)); manifest <- read.csv(args$manifest, stringsAsFactors = FALSE); facilities <- read.csv(args$facilities, stringsAsFactors = FALSE); cfg <- read_facility_exchange_config(args$config); if (args$write) cfg$outputs$root_directory <- args$run_root; result <- assemble_multirun_facility_connectivity(manifest, facilities, cfg, args$run_root, !args$stop_on_error, args$write, args$overwrite); x <- result$combined_exchange_table; cat("manifest_runs:", nrow(result$run_inventory), "\neligible_runs:", sum(result$run_inventory$available_for_processing), "\nprocessed_runs:", sum(result$run_processing_log$processing_status == "processed"), "\nfailed_runs:", nrow(result$failed_runs), "\nexchange_rows:", nrow(x), "\nintercept_rows:", if (nrow(x)) sum(x$intercept) else 0, "\nunique_sources:", if (nrow(x)) length(unique(x$source_id)) else 0, "\nunique_receptors:", if (nrow(x)) length(unique(x$receptor_id)) else 0, "\nunique_directed_dyads:", if (nrow(x)) length(unique(x$source_receptor_id)) else 0, "\noutput_directory:", file.path(args$run_root, "multirun"), "\n") }, error = function(e) { message("ERROR: ", conditionMessage(e)); quit(save = "no", status = 1L) })
